NavigationPanel: FC<NavigationPanelProps> = memo(
  ({
    items,
    labels,
    logo,
    footer,
    renderLink = renderPlainLink,
    styles: panelStyles,
  }) => {
    const { colors, typography, className, cssVars } = panelStyles ?? {};

    const railCssVars = useMemo(
      () =>
        buildCssVars({
          '--np-bg': colors?.background,
          '--np-item-text': colors?.itemText,
          '--np-item-active-text': colors?.itemActiveText,
          '--np-item-selected-bg': colors?.itemSelectedBackground,
          '--np-item-hover-bg': colors?.itemHoverBackground,
          '--np-item-active-bg': colors?.itemActiveBackground,
          '--np-font-family': typography?.fontFamily,
        }),
      [colors, typography?.fontFamily],
    );

    return (
      <nav
        aria-label={labels.ariaLabel}
        style={{ ...cssVars, ...railCssVars }}
        className={mergeClasses(
          styles.rail,
          'relative z-10 flex h-full w-[60px] flex-col justify-between shadow-sm',
          typography?.fontClassName,
          className,
          NAVIGATION_PANEL_CLASS.rail,
        )}
      >
        <div className="flex flex-col items-center">
          {logo && (
            <a
              href={logo.href ?? '/'}
              aria-label={logo.ariaLabel}
              className="flex h-16 w-full shrink-0 items-center justify-center"
            >
              <span
                style={{ backgroundImage: `url(${logo.iconUrl})` }}
                className="h-6 w-6 bg-contain bg-center bg-no-repeat"
              />
            </a>
          )}
          <div className="flex flex-col items-center gap-2 p-2">
            {items.map((item) => (
              <Fragment key={item.id}>
                {renderLink(
                  item,
                  <IconButton
                    icon={
                      <item.icon
                        size={DIAL_ICON_SIZE.LG}
                        stroke={DIAL_KIT_ICON_STROKE}
                      />
                    }
                    aria-label={item.label}
                    aria-current={item.isActive ? 'page' : undefined}
                    tooltipProps={{ tooltip: item.label }}
                    tabIndex={-1}
                    className={mergeClasses(
                      styles.item,
                      'rounded-xl',
                      item.isActive && styles.itemActive,
                      NAVIGATION_PANEL_CLASS.item,
                    )}
                  />,
                )}
              </Fragment>
            ))}
          </div>
        </div>
        {footer}
      </nav>
    );
  },
)

UserMenu: FC<UserMenuProps> = memo(
  ({
    profile,
    labels,
    groups,
    onLogout,
    onSettings,
    isTooltipHidden,
    styles: menuStyles,
  }) => {
    const { colors, typography, className, cssVars } = menuStyles ?? {};
    const labelClassName = typography?.fontClassName ?? 'dial-small-text';

    const menuCssVars = useMemo(
      () =>
        buildCssVars({
          '--np-avatar-bg': colors?.avatarBackground,
          '--np-avatar-text': colors?.avatarText,
          '--np-menu-text': colors?.text,
          '--np-trigger-hover-bg': colors?.triggerHoverBackground,
          '--np-font-family': typography?.fontFamily,
        }),
      [colors, typography?.fontFamily],
    );

    const menuLabelClassName = useMemo(
      () => mergeClasses(styles.menuLabel, labelClassName),
      [labelClassName],
    );

    const items = useMemo<DropdownItem[]>(() => {
      const groupItems = (groups ?? [])
        .filter(({ options }) => options.length > 0)
        .map(({ id, label, icon, options }) => ({
          key: id,
          label: <span className={menuLabelClassName}>{label}</span>,
          icon,
          children: options.map((option) => ({
            key: option.id,
            label: <span className={menuLabelClassName}>{option.label}</span>,
            icon: option.icon,
            /* The applied value is the menu's single choice, so the kit draws
               the trailing check and announces the row as a radio item. */
            mark: MenuItemMark.Check,
            checked: option.isActive,
            onClick: option.onSelect,
          })),
        }));

      return [
        {
          key: 'identity',
          type: DropdownItemType.PlainText,
          label: (
            <div className="flex h-[40px] min-w-0 items-center gap-3">
              <AvatarInitials shortName={profile.shortName} />
              <EllipsisTooltip
                text={profile.displayName}
                className={mergeClasses(
                  styles.identityText,
                  labelClassName,
                  'min-w-0 flex-1 truncate',
                )}
              />
            </div>
          ),
        },
        ...groupItems,
        { key: 'divider-1', type: DropdownItemType.Divider },
        ...(onSettings
          ? [
              {
                key: 'settings',
                label: (
                  <span className={menuLabelClassName}>{labels.settings}</span>
                ),
                icon: (
                  <IconSettings
                    size={DIAL_ICON_SIZE.SM}
                    aria-hidden
                    stroke={DIAL_KIT_ICON_STROKE}
                  />
                ),
                onClick: onSettings,
              },
            ]
          : []),
        {
          key: 'logout',
          label: <span className={menuLabelClassName}>{labels.logOut}</span>,
          icon: (
            <IconLogout
              size={DIAL_ICON_SIZE.SM}
              aria-hidden
              stroke={DIAL_KIT_ICON_STROKE}
            />
          ),
          onClick: onLogout,
        },
      ];
    }, [
      groups,
      labelClassName,
      menuLabelClassName,
      labels.logOut,
      labels.settings,
      onLogout,
      onSettings,
      profile.displayName,
      profile.shortName,
    ]);

    return (
      <div
        style={{ ...cssVars, ...menuCssVars }}
        className={mergeClasses(
          styles.wrapper,
          'flex size-[60px] items-center justify-center',
          className,
        )}
      >
        <Dropdown placement="top-end" matchReferenceWidth={false} items={items}>
          <button
            type="button"
            className={mergeClasses(
              styles.trigger,
              'flex size-[44px] items-center justify-center rounded-full border border-transparent',
            )}
            aria-label={labels.trigger}
          >
            <Tooltip tooltip={profile.email} hideTooltip={isTooltipHidden}>
              <UserAvatar profile={profile} alt={labels.avatarAlt} />
            </Tooltip>
          </button>
        </Dropdown>
      </div>
    );
  },
)

NavigationSheet: FC<NavigationSheetProps> = memo(
  ({
    isOpen,
    onClose,
    items,
    onSelectItem,
    labels,
    profile,
    groups,
    onLogout,
    footer,
    styles: sheetStyles,
  }) => {
    const { colors, typography, className, cssVars } = sheetStyles ?? {};

    const sheetCssVars = useMemo(
      () =>
        buildCssVars({
          '--np-sheet-text': colors?.text,
          '--np-sheet-item-hover': colors?.itemHoverBackground,
          '--np-sheet-item-active': colors?.itemActiveBackground,
          '--np-sheet-row-active-text': colors?.activeRowText,
          '--np-sheet-row-active-bg': colors?.activeRowBackground,
          '--np-sheet-row-active-bg-hover': colors?.activeRowBackgroundHover,
          '--np-sheet-icon': colors?.icon,
          '--np-sheet-divider': colors?.divider,
          '--np-avatar-bg': colors?.avatarBackground,
          '--np-avatar-text': colors?.avatarText,
          '--np-menu-active-icon': colors?.activeIcon,
          '--np-font-family': typography?.fontFamily,
        }),
      [colors, typography?.fontFamily],
    );

    return (
      <NavigableBottomSheet
        isOpen={isOpen}
        onClose={onClose}
        title={labels.title}
        closeLabel={labels.close}
        backLabel={labels.back}
        className={mergeClasses(styles.sheet, className)}
        style={{ ...cssVars, ...sheetCssVars }}
      >
        <NavigationMenuPage
          items={items}
          onSelectItem={onSelectItem}
          profileLabel={labels.profile}
          logOutLabel={labels.logOut}
          onLogout={onLogout}
          profile={profile}
          groups={groups}
          footer={footer}
          textClassName={typography?.fontClassName}
        />
      </NavigableBottomSheet>
    );
  },
)

NavigableBottomSheet: FC<NavigableBottomSheetProps> = memo(
  ({
    isOpen,
    onClose,
    children,
    title,
    closeLabel,
    backLabel,
    className,
    style,
  }) => {
    const [stack, setStack] = useState<SheetPage[]>([]);

    useEffect(() => {
      if (!isOpen) setStack([]);
    }, [isOpen]);

    const push = useCallback((page: SheetPage) => {
      setStack((prev) => [...prev, page]);
    }, []);

    const pop = useCallback(() => {
      setStack((prev) => prev.slice(0, -1));
    }, []);

    const close = useCallback(() => {
      setStack([]);
      onClose();
    }, [onClose]);

    const contextValue = useMemo(
      () => ({ push, pop, close }),
      [push, pop, close],
    );

    const topPage = stack[stack.length - 1];

    return (
      <SheetNavigationContext.Provider value={contextValue}>
        <BottomSheetShell
          isOpen={isOpen}
          onClose={close}
          title={topPage?.title ?? title}
          closeLabel={closeLabel}
          onBack={topPage ? pop : undefined}
          backLabel={topPage ? backLabel : undefined}
          className={className}
          style={style}
        >
          {topPage ? topPage.content : children}
        </BottomSheetShell>
      </SheetNavigationContext.Provider>
    );
  },
)

NavigationMenuPage: FC<NavigationMenuPageProps> = memo(
  ({
    items,
    onSelectItem,
    profileLabel,
    logOutLabel,
    onLogout,
    profile,
    groups,
    footer,
    textClassName,
  }) => {
    const { push, close } = useSheetNavigation();

    const handleSelectItem = (item: NavigationPanelItem) => {
      close();
      onSelectItem(item);
    };

    const handleOpenProfile = () => {
      if (!profile) return;
      push({
        title: profileLabel,
        content: (
          <ProfilePage
            profile={profile}
            groups={groups}
            logOutLabel={logOutLabel}
            onLogout={onLogout}
            textClassName={textClassName}
          />
        ),
      });
    };

    return (
      <>
        <ul className="flex flex-col pb-4">
          {items.map((item) => (
            <SheetRow
              key={item.id}
              label={item.label}
              textClassName={textClassName}
              isCurrent={item.isActive}
              isHighlighted={item.isActive}
              icon={
                <item.icon
                  size={BASE_ICON_SIZE}
                  stroke={DIAL_KIT_ICON_STROKE}
                />
              }
              onClick={() => handleSelectItem(item)}
            />
          ))}
          {profile && (
            <SheetRow
              label={profileLabel}
              textClassName={textClassName}
              icon={
                <IconUser
                  size={BASE_ICON_SIZE}
                  stroke={DIAL_KIT_ICON_STROKE}
                  aria-hidden
                />
              }
              onClick={handleOpenProfile}
            />
          )}
        </ul>
        {footer}
      </>
    );
  },
)

ProfilePage: FC<ProfilePageProps> = memo(
  ({
    profile,
    logOutLabel,
    onLogout,
    groups,
    textClassName = 'dial-small-text',
  }) => {
    const { push, close } = useSheetNavigation();

    const settingsGroups = (groups ?? []).filter(
      ({ options }) => options.length > 0,
    );

    const handleLogout = () => {
      close();
      onLogout();
    };

    return (
      <>
        <div className="flex h-[56px] items-center gap-3 px-4 py-2">
          <UserAvatar profile={profile} alt="" />
          <EllipsisTooltip
            text={profile.displayName}
            className={mergeClasses(
              styles.mutedText,
              textClassName,
              'min-w-0 flex-1 truncate',
            )}
          />
        </div>

        {settingsGroups.length > 0 && (
          <>
            <ul className="flex flex-col">
              {settingsGroups.map((group) => (
                <SheetRow
                  key={group.id}
                  label={group.label}
                  icon={group.icon}
                  textClassName={textClassName}
                  trailing={
                    <IconChevronRight
                      size={BASE_ICON_SIZE}
                      stroke={DIAL_KIT_ICON_STROKE}
                      aria-hidden
                      className={mergeClasses(
                        styles.rowIcon,
                        'rtl:scale-x-[-1]',
                      )}
                    />
                  }
                  onClick={() =>
                    push({
                      title: group.label,
                      content: (
                        <OptionListPage
                          options={group.options}
                          textClassName={textClassName}
                        />
                      ),
                    })
                  }
                />
              ))}
            </ul>

            <hr className={styles.divider} />
          </>
        )}

        <ul className="flex flex-col pb-4">
          <SheetRow
            label={logOutLabel}
            textClassName={textClassName}
            icon={
              <IconLogout
                size={BASE_ICON_SIZE}
                stroke={DIAL_KIT_ICON_STROKE}
                aria-hidden
              />
            }
            onClick={handleLogout}
          />
        </ul>
      </>
    );
  },
)

OptionListPage: FC<OptionListPageProps> = memo(
  ({ options, textClassName }) => {
    const { pop } = useSheetNavigation();

    return (
      <ul className="flex flex-col pb-4">
        {options.map((option) => (
          <SheetRow
            key={option.id}
            label={option.label}
            icon={option.icon}
            textClassName={textClassName}
            /* The applied value is the current one of the group; the design
               marks it with the trailing check, not with a tint. */
            isCurrent={option.isActive}
            trailing={
              option.isActive ? (
                <IconCheck
                  size={DIAL_ICON_SIZE.SM}
                  stroke={DIAL_KIT_ICON_STROKE}
                  aria-hidden
                  className={styles.activeIcon}
                />
              ) : undefined
            }
            onClick={() => {
              option.onSelect();
              pop();
            }}
          />
        ))}
      </ul>
    );
  },
)

SheetRow: FC<SheetRowProps> = memo(
  ({
    label,
    onClick,
    icon,
    trailing,
    isCurrent = false,
    isHighlighted = false,
    textClassName = 'dial-small-text',
  }) => (
    <li>
      <button
        type="button"
        aria-current={isCurrent ? 'true' : undefined}
        className={mergeClasses(
          styles.row,
          isHighlighted && styles.rowActive,
          'flex w-full items-center gap-3 px-4 py-[10px] text-start',
        )}
        onClick={onClick}
      >
        {icon && <span className={styles.rowIcon}>{icon}</span>}
        <span className={mergeClasses(textClassName, 'flex-1')}>{label}</span>
        {trailing}
      </button>
    </li>
  ),
)

AvatarInitials: FC<AvatarInitialsProps> = memo(
  ({ shortName, className, textClassName = 'dial-tiny-text' }) => (
    <div
      className={mergeClasses(
        styles.avatar,
        'flex size-[28px] flex-shrink-0 items-center justify-center rounded-full',
        textClassName,
        className,
      )}
    >
      {shortName}
    </div>
  ),
)

UserAvatar: FC<UserAvatarProps> = memo(({ profile, alt }) =>
  profile.isFallbackShown || !profile.imageUrl ? (
    <AvatarInitials shortName={profile.shortName} />
  ) : (
    // eslint-disable-next-line jsx-a11y/no-noninteractive-element-interactions
    <img
      className="rounded-full"
      src={profile.imageUrl}
      width={28}
      height={28}
      alt={alt}
      onError={profile.onImageError}
    />
  ),
)

useSheetNavigation = (): SheetNavigation => {
  const ctx = useContext(SheetNavigationContext);
  if (!ctx) {
    throw new Error(
      'useSheetNavigation must be used within a NavigableBottomSheet',
    );
  }
  return ctx;
}

export type NavigationLinkRenderer = (
  item: NavigationPanelItem,
  children: ReactNode,
) => ReactNode;

export interface NavigationPanelItem {
  /** Stable identity used as the React key and as the `onSelect` discriminator. */
  id: string;
  /** Translated label used as the accessible name, tooltip, and sheet row text. */
  label: string;
  /** Icon component rendered inside the rail button and the sheet row. */
  icon: NavigationItemIcon;
  /** Whether this entry points at the page currently on screen. */
  isActive?: boolean;
  /** Target URL placed on the rail anchor. The host owns route matching and navigation. */
  href?: string;
}

export interface NavigationMenuGroup {
  /** Stable identity used as the React key. */
  id: string;
  /** Translated group label shown on the parent row and as the sheet page title. */
  label: string;
  /** Optional leading icon for the parent row. */
  icon?: ReactNode;
  /** Options belonging to the group; a group with no options is skipped. */
  options: NavigationMenuOption[];
}

export interface NavigationMenuOption {
  /** Stable identity used as the React key. */
  id: string;
  /** Translated option label. */
  label: string;
  /** Whether this option is the currently applied value; renders a check mark. */
  isActive: boolean;
  /** Optional leading icon. */
  icon?: ReactNode;
  /** Applies the option. */
  onSelect: () => void;
}

export interface NavigationPanelColors {
  /** Rail background color. */
  background?: string;
  /** Icon color of an inactive item. */
  itemText?: string;
  /** Icon color of the active item. */
  itemActiveText?: string;
  /** Background of the active/selected item. */
  itemSelectedBackground?: string;
  /** Item background on hover. */
  itemHoverBackground?: string;
  /** Item background while pressed. */
  itemActiveBackground?: string;
}

export interface NavigationPanelLabels {
  /** Accessible name for the `<nav>` landmark. */
  ariaLabel: string;
}

export interface NavigationPanelLogo {
  /** Image URL used as the mark's `background-image`. */
  iconUrl: string;
  /** Link target for the mark. Defaults to `'/'`. */
  href?: string;
  /** Translated accessible name for the logo link. */
  ariaLabel: string;
}

export interface NavigationPanelProps {
  /** Destinations rendered as icon buttons, in display order. */
  items: NavigationPanelItem[];
  /** Translated labels for the landmark. */
  labels: NavigationPanelLabels;
  /** Brand mark shown above the items; omit to render no logo. */
  logo?: NavigationPanelLogo;
  /** Pinned to the bottom of the rail — typically `UserMenu`. */
  footer?: ReactNode;
  /** Wraps each item in a host-owned link element. Defaults to a plain `<a href>`. */
  renderLink?: NavigationLinkRenderer;
  /** Style overrides for colors, typography, and class names. */
  styles?: NavigationPanelStyles;
}

export interface NavigationPanelStyles {
  /** Color overrides applied as CSS custom properties. */
  colors?: NavigationPanelColors;
  /** Typography overrides applied to the rail root. */
  typography?: NavigationPanelTypography;
  /** Extra class name(s) merged onto the `<nav>` element. */
  className?: string;
  /** CSS custom properties applied to the `<nav>` element. */
  cssVars?: CSSProperties;
}

export interface NavigationPanelTypography {
  /** CSS class applied to the rail root, inherited by all rail content. */
  fontClassName?: string;
  /** `font-family` applied to the rail root. */
  fontFamily?: string;
}

export interface NavigationSheetColors {
  /** Row label text color. */
  text?: string;
  /** Row background on hover. */
  itemHoverBackground?: string;
  /** Row background while pressed. */
  itemActiveBackground?: string;
  /** Label and icon color of the row whose destination is open. */
  activeRowText?: string;
  /** Background of the row whose destination is open. */
  activeRowBackground?: string;
  /** Background of the row whose destination is open, on hover. */
  activeRowBackgroundHover?: string;
  /** Row leading-icon color. */
  icon?: string;
  /** Divider color between row groups. */
  divider?: string;
  /** Avatar initials-badge background. */
  avatarBackground?: string;
  /** Avatar initials text color. */
  avatarText?: string;
  /** Check-mark color marking the active option. */
  activeIcon?: string;
}

export interface NavigationSheetLabels {
  /** Root-page header title, e.g. `"Menu"`. */
  title: string;
  /** Accessible name for the close (×) button. */
  close: string;
  /** Accessible name for the back button shown on pushed pages. */
  back: string;
  /** Label of the row that opens the profile page, also its page title. */
  profile: string;
  /** Label of the log-out row. */
  logOut: string;
}

export interface NavigationSheetProps {
  /** Controls sheet visibility. */
  isOpen: boolean;
  /** Called when the sheet should close (backdrop tap, close button, or Escape). */
  onClose: () => void;
  /** Destinations rendered as rows on the root page, in display order. */
  items: NavigationPanelItem[];
  /** Called with the picked destination; the host performs the navigation. */
  onSelectItem: (item: NavigationPanelItem) => void;
  /** Translated labels for the header, profile row, and log-out row. */
  labels: NavigationSheetLabels;
  /** Signed-in user details shown on the profile page; omit to hide the profile row. */
  profile?: NavigationUserProfile;
  /** Single-select settings groups listed on the profile page; empty groups are skipped. */
  groups?: NavigationMenuGroup[];
  /** Called when the user taps "Log out"; the host owns the confirmation flow. */
  onLogout: () => void;
  /** Rendered at the end of the root page — typically a footer message. */
  footer?: ReactNode;
  /** Style overrides for colors, typography, and class names. */
  styles?: NavigationSheetStyles;
}

export interface NavigationSheetStyles {
  /** Color overrides applied as CSS custom properties. */
  colors?: NavigationSheetColors;
  /** Typography overrides applied to row labels. */
  typography?: NavigationSheetTypography;
  /** Extra class name(s) merged onto the sheet container. */
  className?: string;
  /** CSS custom properties applied to the sheet container. */
  cssVars?: CSSProperties;
}

export interface NavigationSheetTypography {
  /** CSS class applied to row labels. Defaults to `'dial-small-text'`. */
  fontClassName?: string;
  /** `font-family` applied to the sheet content. */
  fontFamily?: string;
}

export interface SheetNavigation {
  /** Pushes a page on top of the stack. */
  push: (page: SheetPage) => void;
  /** Pops the top page, revealing the one beneath it. */
  pop: () => void;
  /** Clears the stack and closes the sheet. */
  close: () => void;
}

export interface SheetPage {
  /** Header title shown while the page is on top of the stack. */
  title: string;
  /** Page body. */
  content: ReactNode;
}

export interface UserMenuColors {
  /** Avatar initials-badge background. */
  avatarBackground?: string;
  /** Avatar initials text color. */
  avatarText?: string;
  /** Menu label text color. */
  text?: string;
  /** Trigger background on hover. */
  triggerHoverBackground?: string;
}

export interface UserMenuLabels {
  /** Accessible name for the avatar trigger, e.g. `"Signed in as a@b.c"`. */
  trigger: string;
  /** Alternative text for the avatar image. */
  avatarAlt: string;
  /** Label of the log-out entry. */
  logOut: string;
  /** Label of the settings entry; required when `onSettings` is provided. */
  settings?: string;
}

export interface UserMenuProps {
  /** Signed-in user details used for the identity row and avatar. */
  profile: NavigationUserProfile;
  /** Translated labels for the trigger, avatar, and log-out entry. */
  labels: UserMenuLabels;
  /** Single-select settings groups rendered as submenus; empty groups are skipped. */
  groups?: NavigationMenuGroup[];
